resources.description:
Обновляет карточку компании. fields — мердж на уровне поля.

С шаблоном, исключение:  { value: ..., isException: true }
С шаблоном, из шаблона:  { isException: false }
Без шаблона:             { value: ... }

Поддерживает platform-override: platforms: { yandex: <overrideValue> }

body.text:
{
  "fields": {
    "names": {
      "value": [
        { "lang": "ru", "val": "Обновлённое название" }
      ],
      "isException": true,
      "platforms": {
        "yandex": [
          { "lang": "ru", "val": "Название для Яндекса" }
        ]
      }
    },
    "phones": {
      "value": [
        { "phone": "+79001234567", "ext": "", "description": "Основной", "hidden": false }
      ],
      "isException": true
    }
  }
}
